import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const root = process.argv[2]
const repo = 'https://github.com/orin-dx/caliper'
const base = ['react', 'docgen', 'typescript', 'oxc']

function enrich(dir, extra, description) {
  const file = join(root, dir, 'package.json')
  const pkg = JSON.parse(readFileSync(file, 'utf8'))
  const out = {}
  for (const [k, v] of Object.entries(pkg)) {
    if (k === 'keywords' || k === 'homepage' || k === 'bugs') continue
    out[k] = k === 'description' && description ? description : v
    if (k === 'description') {
      out.keywords = [...base, ...extra]
      out.homepage = `${repo}#readme`
      out.bugs = { url: `${repo}/issues` }
    }
  }
  out.repository = { type: 'git', url: 'git+https://github.com/orin-dx/caliper.git', directory: dir }
  writeFileSync(file, JSON.stringify(out, null, 2) + '\n')
  return pkg.name
}

enrich('packages/cli', ['cli', 'storybook'], 'Fast React component prop extraction CLI, powered by OXC')
enrich('packages/napi', ['napi', 'native'])
enrich('packages/vite-plugin', ['vite', 'vite-plugin', 'storybook'])
for (const p of readdirSync(join(root, 'packages/cli/npm'))) enrich(`packages/cli/npm/${p}`, ['cli', 'binary'])
for (const p of readdirSync(join(root, 'packages/napi/npm'))) enrich(`packages/napi/npm/${p}`, ['napi', 'native'])

function platformReadme(dir, ownerName) {
  const pkg = JSON.parse(readFileSync(join(root, dir, 'package.json'), 'utf8'))
  const text = `# ${pkg.name}\n\nPlatform binary for [${ownerName}](https://www.npmjs.com/package/${ownerName}). Don't install it directly: \`${ownerName}\` pulls in the right one for your OS and CPU as an optional dependency.\n\nSource and docs: ${repo}\n`
  writeFileSync(join(root, dir, 'README.md'), text)
}
for (const p of readdirSync(join(root, 'packages/cli/npm'))) platformReadme(`packages/cli/npm/${p}`, 'caliper-docgen')
for (const p of readdirSync(join(root, 'packages/napi/npm'))) platformReadme(`packages/napi/npm/${p}`, 'caliper-docgen-napi')
console.log('ok')

