import re, sys, pathlib

DEFAULTS = {'Vec::new()', 'vec![]', 'Default::default()', 'FxHashMap::default()', 'String::new()', 'BTreeMap::new()', 'std::string::String::new()'}


def split_top(body):
    parts, depth, cur, instr = [], 0, '', False
    i = 0
    while i < len(body):
        c = body[i]
        if instr:
            cur += c
            if c == '\\':
                cur += body[i + 1]
                i += 1
            elif c == '"':
                instr = False
        elif c == '"':
            instr = True
            cur += c
        elif c in '([{':
            depth += 1
            cur += c
        elif c in ')]}':
            depth -= 1
            cur += c
        elif c == ',' and depth == 0:
            parts.append(cur)
            cur = ''
        else:
            cur += c
        i += 1
    if cur.strip():
        parts.append(cur)
    return [p.strip() for p in parts if p.strip()]


for arg in sys.argv[1:]:
    p = pathlib.Path(arg)
    s = p.read_text()
    out = []
    i = 0
    n = 0
    while True:
        m = re.compile(r'ComponentMapping \{').search(s, i)
        if not m:
            out.append(s[i:])
            break
        out.append(s[i:m.start()])
        j = m.end()
        depth = 1
        instr = False
        while depth:
            c = s[j]
            if instr:
                if c == '\\':
                    j += 1
                elif c == '"':
                    instr = False
            elif c == '"':
                instr = True
            elif c == '{':
                depth += 1
            elif c == '}':
                depth -= 1
            j += 1
        body = s[m.end():j - 1]
        fields = {}
        for part in split_top(body):
            if re.match(r'^[a-z_]+\s*:[^:]', part):
                k, v = part.split(':', 1)
                fields[k.strip()] = v.strip()
            else:
                fields[part] = part
        need = ['component_name', 'props_type_name', 'file_path', 'span_start', 'span_end']
        call = 'ComponentMapping::new(' + ', '.join(fields[k] for k in need) + ')'
        if fields.get('props_type_args', 'Vec::new()') not in DEFAULTS:
            call += f".with_props_type_args({fields['props_type_args']})"
        d, t = fields.get('description', 'String::new()'), fields.get('tags', 'Default::default()')
        if d not in DEFAULTS or t not in DEFAULTS:
            call += f'.with_doc({d}, {t})'
        if fields.get('param_defaults', 'Default::default()') not in DEFAULTS:
            call += f".with_param_defaults({fields['param_defaults']})"
        out.append(call)
        i = j
        n += 1
    p.write_text(''.join(out))
    print(arg, n)

