        props_type_name: TypeName,
        file_path: Utf8PathBuf,
        span_start: u32,
        span_end: u32,
    ) -> Self {
        Self {
            component_name: component_name.into(),
            props_type_name,
            props_type_args: Vec::new(),
            file_path,
            description: std::string::String::new(),
            tags: BTreeMap::new(),
            span_start,
            span_end,
            param_defaults: FxHashMap::default(),
        }
    }

