"""Write a scratch project from a dict of files, extract it with the pinned binary, print components and diagnostics.

Usage: python3 repro.py <case-name>   (cases defined below)
"""
import json, pathlib, subprocess, sys, shutil

BIN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/caliper-docgen-08bafb04'
ROOT = pathlib.Path('/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/vet/cases')

CASES = {
    'wrapper_fp': {
        'a.tsx': 'interface ButtonProps { label?: string }\n'
                 'export const Button = makeLabel<ButtonProps>("button");\n'
                 'export const ButtonSchema = z.object<ButtonProps>(shape);\n'
                 'export const ButtonStore = createStore<ButtonProps>(initial);\n',
    },
    'quoted_param': {
        'a.tsx': 'interface Base { T: string; number: boolean; other: number }\n'
                 'interface Wrap<T> extends Pick<Base, "T"> { own: T }\n'
                 'export function A(props: Wrap<number>) { return null }\n',
    },
    'wrapper_silent_reject': {
        'a.tsx': 'export const Thing = makeThing<Opaque>("div");\n',
    },
    'arrow_in_generic': {
        'a.tsx': 'interface Box<T> { value: T }\n'
                 'export function A(props: Box<() => void>) { return null }\n'
                 'export function B(props: Box<(a: string) => number | string>) { return null }\n',
    },
    'infinity_ident': {
        'a.tsx': 'type Infinity = { x: string };\n'
                 'interface Box<T> { value: T }\n'
                 'export function A(props: Box<Infinity>) { return null }\n',
    },
}


def run(name):
    files = CASES[name]
    d = ROOT / name
    if d.exists():
        shutil.rmtree(d)
    d.mkdir(parents=True)
    (d / 'package.json').write_text('{"name":"x","private":true}\n')
    for rel, body in files.items():
        p = d / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(body)
    out = subprocess.run([BIN, 'extract', '--src', str(d), '--format', 'canonical', '--json'], capture_output=True, text=True)
    data = json.loads(out.stdout)
    print(f'== {name}')
    for k, c in data['components'].items():
        props = {p: json.dumps(v['type'], separators=(',', ':'))[:90] for p, v in c['props'].items()}
        print(f'  {k}: {props}')
    for x in data['diagnostics']:
        print(f"  diag {x['code']} {x['severity']}: {x['message'][:150]}")


for n in sys.argv[1:] or CASES:
    run(n)

