/// Literals, `null` and object or array values rule out context defaults, option bags and constants.
fn plausible_component_argument(arg: Option<&Argument<'_>>) -> bool {
    let Some(expr) = arg.and_then(Argument::as_expression) else { return false };
    matches!(
        expr,
        Expression::ArrowFunctionExpression(_)
            | Expression::FunctionExpression(_)
            | Expression::StringLiteral(_)
            | Expression::Identifier(_)
            | Expression::CallExpression(_)
            | Expression::StaticMemberExpression(_)
    )
}
''', '''fn is_element_type_arg(ty: &TSType<'_>) -> bool {
    match ty {
        TSType::TSTypeReference(r) => match &r.type_name {
            TSTypeName::IdentifierReference(id) => is_element_type(id.name.as_str()),
            TSTypeName::QualifiedName(q) => is_element_type(q.right.name.as_str()),
            _ => false,
        },
        _ => false,
    }
}

fn is_component_reference(name: &str) -> bool {
    name.starts_with(|c: char| c.is_ascii_uppercase())
}

/// Evidence that the call builds a component from its first argument: a function that renders (Mantine's
/// `factory<F>((props) => <Box />)`), a tag name next to an element type argument (`withContext<HTMLDivElement, P>("div")`),
/// or a reference to a component (`withRootProvider<P>(Ark.Root)`). A tag string alone also describes
/// `makeLabel<P>("button")`, and a lowercase value describes a context default or a store, so neither counts.
fn component_argument_evidence(callee: &str, call: &CallExpression<'_>) -> Result<(), &'static str> {
    if callee.rsplit('.').next() == Some("createContext") {
        return Err("creates a context");
    }
    let Some(first) = call.arguments.first().and_then(Argument::as_expression) else {
        return Err("has no argument that could be a component");
    };
    let element_type_arg = || call.type_arguments.as_ref().is_some_and(|a| a.params.iter().any(is_element_type_arg));
    match first {
        Expression::ArrowFunctionExpression(f) => {
            renders(&FunctionShape::of_arrow(f)).map_err(|_| "is given a function that never renders")
        }
        Expression::FunctionExpression(f) => {
            renders(&FunctionShape::of_function(f)).map_err(|_| "is given a function that never renders")
        }
        Expression::StringLiteral(_) if element_type_arg() => Ok(()),
        Expression::StringLiteral(_) => Err("is given a tag name with no element type argument"),
        Expression::Identifier(id) if is_component_reference(id.name.as_str()) => Ok(()),
        Expression::StaticMemberExpression(m) if is_component_reference(m.property.name.as_str()) => Ok(()),
        _ => Err("is given an argument that is not a render function, a tag or a component reference"),
    }
}
