IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
RES = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-results'


def clean(n):
    return re.sub(r' \(.*\)$', '', n)


def norm(n):
    n = clean(n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


def plausible(name):
    b = clean(name).split('/')[-1].split('.')[-1]
    return bool(re.match(r'[A-Z]', b)) and not re.match(r'use[A-Z]', b)


