"""Diff one fixture dir's component prop types between two binaries. Usage: fixture_diff.py A B dir"""
import json, subprocess, sys

A, B, d = sys.argv[1:4]


def run(b):
    return json.loads(subprocess.run([b, 'extract', '--src', d, '--json'], capture_output=True, text=True).stdout)


a, b = run(A), run(B)
for k in sorted(set(a['components']) | set(b['components'])):
    pa = a['components'].get(k, {}).get('props', {})
    pb = b['components'].get(k, {}).get('props', {})
    for p in sorted(set(pa) | set(pb)):
        ta = json.dumps(pa.get(p, {}).get('type'))[:160]
        tb = json.dumps(pb.get(p, {}).get('type'))[:160]
        if ta != tb:
            print(f'{k}.{p}\n   A {ta}\n   B {tb}')
    ca, cb = a['components'].get(k, {}).get('composes'), b['components'].get(k, {}).get('composes')
    if ca != cb:
        print(f'{k} composes: {ca} -> {cb}')
print('diags A', len(a['diagnostics']), 'B', len(b['diagnostics']))

