import json, subprocess, sys
from collections import Counter

A, B, proj = sys.argv[1:4]
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'


def run(b):
    return json.loads(subprocess.run([b, 'extract', '--src', f'{IN}/{proj}', '--json'], capture_output=True, text=True).stdout)


a, b = run(A), run(B)
changed = Counter()
samples = {}
size_a = size_b = 0
for k, ca in a['components'].items():
    cb = b['components'].get(k)
    if not cb:
        continue
    for p, va in ca['props'].items():
        vb = cb['props'].get(p)
        if not vb:
            continue
        ta, tb = json.dumps(va['type']), json.dumps(vb['type'])
        size_a += len(ta)
        size_b += len(tb)
        if ta != tb:
            key = ta[:70]
            changed[key] += 1
            samples.setdefault(key, (k, p, ta[:150], tb[:220], len(tb)))
print(f'changed prop types: {sum(changed.values())}; type JSON bytes A={size_a} B={size_b}; diags A={len(a["diagnostics"])} B={len(b["diagnostics"])}')
for key, n in changed.most_common(8):
    k, p, ta, tb, lb = samples[key]
    print(f'x{n} {k}.{p}\n   A {ta}\n   B ({lb} chars) {tb}')

