//! Which source files a component's resolution read, so watch mode re-resolves exactly the components an edit can
//! change. A component resolves on one thread from start to finish, so the recorder is thread-local and scoped to one
//! `resolve_component` call; lookups record into it without every resolver function threading a collector through.

use std::cell::RefCell;

use camino::{Utf8Path, Utf8PathBuf};
use rustc_hash::FxHashSet;

thread_local! {
    static RECORDER: RefCell<Option<FxHashSet<Utf8PathBuf>>> = const { RefCell::new(None) };
}

/// Note that the current resolution read `file`. A no-op outside `recording`.
pub(super) fn record(file: &Utf8Path) {
    RECORDER.with(|recorder| {
        if let Some(files) = recorder.borrow_mut().as_mut() {
            if !files.contains(file) {
                files.insert(file.to_owned());
            }
        }
    });
}

/// Run `f` and return the files it read. Not reentrant: resolution never nests a component inside another.
pub(super) fn recording<T>(f: impl FnOnce() -> T) -> (T, FxHashSet<Utf8PathBuf>) {
    RECORDER.with(|recorder| *recorder.borrow_mut() = Some(FxHashSet::default()));
    let result = f();
    let files = RECORDER.with(|recorder| recorder.borrow_mut().take()).unwrap_or_default();
    (result, files)
}

