use std::time::Instant;

use caliper_docgen_core::pipeline::{PipelineOptions, WatchSession};
use camino::Utf8PathBuf;

fn main() {
    let src = Utf8PathBuf::from(std::env::args().nth(1).expect("src dir"));
    let files: Vec<String> = std::env::args().skip(2).collect();
    let options = PipelineOptions { src_dirs: vec![src.clone()], ..Default::default() };
    let session = WatchSession::new(options);
    let t = Instant::now();
    let _ = session.initialize();
    println!("initialize {:?}", t.elapsed());
    for file in files {
        let path = src.join(&file);
        let original = std::fs::read_to_string(&path).expect("read");
        let mut times = Vec::new();
        let mut updated = 0;
        for n in 0..7 {
            std::fs::write(&path, format!("{original}\n// {n}\n")).expect("write");
            let t = Instant::now();
            let update = session.update_file(&path);
            times.push(t.elapsed());
            updated = update.updated_components.len();
        }
        std::fs::write(&path, &original).expect("restore");
        times.sort();
        println!("{file}: median {:?} min {:?} updated {updated}", times[3], times[0]);
    }
}

