      expect(napi.initializeSession).toHaveBeenCalledTimes(1)
      const code = await (p.load as Function).call(pluginContext(), '\0virtual:caliper-docgen')
      expect(code).toBe(`export default ${SNAPSHOT}`)
    })
  })

