      const p = caliperDocgen({ srcDirs: ['src'] })
      ;(p.configResolved as Function)({ root: '/project' })
      expect(napi.createSession).toHaveBeenCalledWith(expect.objectContaining({ exclude: undefined }))
    })
  })
})

