async watchChange(id: string) {
  if (!isSrcFile(id)) return
  const change = (async () => {
    try {
      await applyChange(id)
    } catch (error) {
      console.error('[caliper-docgen] Failed to apply the change:', error)
    }
  })()
  pendingWatchChanges.push(change)
  await change
},

