"""Insert `affects: Vec::new()` into every Diagnostic struct literal the compiler reports as missing it."""
import collections, json, pathlib, subprocess

ROOT = pathlib.Path('/Users/gabe/Projects/caliper/.claude/worktrees/release-0.2.0')

for round_ in range(5):
    out = subprocess.run(
        ['cargo', 'build', '--workspace', '--all-targets', '--message-format=json'],
        cwd=ROOT, capture_output=True, text=True,
    ).stdout
    sites = collections.defaultdict(set)
    for line in out.splitlines():
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        m = msg.get('message') or {}
        if m.get('code', {}) and (m.get('code') or {}).get('code') == 'E0063' and 'affects' in m.get('message', ''):
            for span in m['spans']:
                if span['is_primary']:
                    sites[span['file_name']].add(span['byte_start'])
    if not sites:
        print('done after', round_, 'rounds')
        break
    for file, starts in sites.items():
        p = ROOT / file
        b = p.read_bytes()
        # Insert from the end so earlier offsets stay valid.
        for start in sorted(starts, reverse=True):
            brace = b.index(b'{', start)
            depth, i = 0, brace
            while True:
                c = b[i:i + 1]
                if c == b'{':
                    depth += 1
                elif c == b'}':
                    depth -= 1
                    if depth == 0:
                        break
                i += 1
            before = b[brace + 1:i].rstrip()
            sep = b'' if before.endswith(b',') or before == b'' else b','
            insertion = sep + b' affects: Vec::new(), '
            b = b[:brace + 1] + before + insertion + b[i:]
        p.write_bytes(b)
        print(file, len(starts))
subprocess.run(['cargo', 'fmt', '--all'], cwd=ROOT)

