def clean(n):
    return re.sub(r' \(.*\)$', '', n)


def norm(n):
    n = clean(n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


def exported(path, name):
    bare = re.split(r'[./]', clean(name))[-1]
    try:
        src = open(path, encoding='utf-8').read()
    except OSError:
        return None
    w = re.escape(bare)
    patterns = [
        rf'export\s+(default\s+)?(const|let|var|function|class|async\s+function)\s+{w}\b',
        rf'export\s*\{{[^}}]*\b{w}\b[^}}]*\}}',
        rf'export\s+default\s+{w}\b',
        rf'export\s+default\s+(memo|forwardRef|React\.memo|React\.forwardRef)\(\s*{w}\b',
    ]
    return any(re.search(p, src) for p in patterns)


