def norm_name(n):
    n = re.sub(r' \(.*\)$', '', n).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', n.lower())


def tidy(t):
    t = (t or '').replace("'", '"')
    t = re.sub(r';\s*}', ' }', t)
    t = re.sub(r';\s*', '; ', t)
    t = re.sub(r'\?: ([^;{}]+?) \| undefined', r'?: \1', t)
    t = re.sub(r'\bReact\.', '', t)
    t = re.sub(r'\s+', ' ', t).strip()
    if t.startswith('((') and t.endswith(')'):
        t = t[1:-1]
    m = re.fullmatch(r'\((\(.*\) => .*)\)', t)
    if m:
        t = m.group(1)
    if '|' in t and not re.search(r'[(<{\[]', t):
        t = ' | '.join(sorted(p.strip() for p in t.split('|')))
    return t


def family(cal, rdt):
    if tidy(cal) == tidy(rdt):
        return 'formatting only'
    if rdt.strip() in ('any', 'unknown'):
        return 'RDT any/unknown (deps not installed)'
    if re.fullmatch(r'\((e: void)?\) => void', cal) and '=>' in rdt and not rdt.rstrip(')').endswith('=> void'):
