    if re.search(r'\(e: [A-Za-z.]*(EventHandler|Handler)[^)]*\) => void', cal):
        return 'handler type wrapped as a parameter'
    if re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', rdt.strip()) and not re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', cal.strip()):
        return 'Caliper expanded an alias RDT names'
    if re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', cal.strip()) and not re.fullmatch(r'[A-Z][\w.]*(<.*>)?(\[\])?', rdt.strip()):
        return 'Caliper kept a name RDT expanded'
    if 'extends' in cal and '?' in cal:
        return 'conditional type left unevaluated'
    if cal.strip() == 'enum' or rdt.strip() == 'enum':
        return '"enum" placeholder'
    return 'other'


