"""How often `typeof X` is opaque although X is a component Caliper itself emitted, and how many components it empties."""
import json, re, subprocess

BIN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/caliper-docgen-next'
IN = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-inputs'
print('| Corpus | components | empty props | opaque typeof of a known component | components affected | of those, empty |')
print('| --- | ---: | ---: | ---: | ---: | ---: |')
for corpus in ['mantine', 'chakra', 'antd', 'shadcn', 'spectrum']:
    out = json.loads(subprocess.run([BIN, 'extract', '--src', f'{IN}/{corpus}', '--json'], capture_output=True,
                                    text=True).stdout)
    comps = out['components']
    known = {(c['filePath'], c['displayName'].split('/')[-1]) for c in comps.values()}
    known_names = {c['displayName'].split('/')[-1] for c in comps.values()}
    empty = {k for k, c in comps.items() if not c['props']}
    hits = affected = 0
    affected_keys = set()
    for d in out.get('diagnostics', []):
        m = re.match(r"typeof '([\w.]+)' in '([^']+)'", d['message'])
        if d.get('code') != 'OPAQUE_TYPE' or not m:
            continue
        name = m.group(1).split('.')[-1]
        if (m.group(2), name) in known or name in known_names:
            hits += 1
            for a in d.get('affects', []):
                affected_keys.add(a)
    by_label = {}
    for k, c in comps.items():
        by_label[f"{c['displayName']} ({c['filePath']})"] = k
        by_label.setdefault(c['displayName'], k)
    keys = {by_label.get(a) for a in affected_keys} - {None}
    print(f'| {corpus} | {len(comps):,} | {len(empty):,} | {hits} | {len(keys)} | {len(keys & empty)} |')

"""Classify how each unexported component Caliper reports is used inside its own file."""
import collections, json, re

D = '/Users/gabe/.claude/jobs/ba6a68d6/tmp/review/precision'
extras = [e for e in json.load(open(f'{D}/extras.json')) if not e['exported']]
kinds = collections.Counter()
per = collections.defaultdict(collections.Counter)
examples = collections.defaultdict(list)
for e in extras:
    name = e['name'].split('/')[-1].split('.')[-1]
    src = open(e['file'], encoding='utf-8', errors='replace').read()
    n = re.escape(name)
    if re.search(rf'export\s*\{{[^}}]*\b{n}\b[^}}]*\}}|export\s+default\s+{n}\b', src):
        kind = 'exported later (flag is wrong)'
    elif re.search(rf'\b\w+\.\w+\s*=\s*{n}\b', src) or re.search(rf'Object\.assign\([^;]*\b{n}\b', src, re.S):
        kind = 'attached to an exported component as a member'
    elif re.search(rf'typeof\s+{n}\b', src):
        kind = 'its type feeds another type (typeof)'
    elif re.search(rf'<{n}[\s/>]', src) or re.search(rf'createElement\(\s*{n}\b', src):
        kind = 'rendered by another component in the file'
    elif len(re.findall(rf'\b{n}\b', src)) > 1:
        kind = 'passed or referenced as a value'
    else:
        kind = 'declared, never referenced'
    kinds[kind] += 1
    per[e['corpus']][kind] += 1
    if len(examples[kind]) < 3:
        examples[kind].append(f"{e['corpus']}:{name}")
print(len(extras), 'unexported')
for k, v in kinds.most_common():
    print(f'{v:4} {k}  e.g. {", ".join(examples[k])}')

