//! Time serializing one ExtractionOutput with serde_json, sonic-rs and simd-json, whole and per component in parallel.
use std::time::Instant;

use caliper_docgen_core::pipeline::{extract, PipelineOptions};
use rayon::prelude::*;

fn median(mut v: Vec<f64>) -> f64 {
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    v[v.len() / 2]
}

fn time<F: FnMut() -> Vec<u8>>(label: &str, reference: &[u8], mut f: F) {
    let mut runs = Vec::new();
    let mut out = Vec::new();
    for _ in 0..31 {
        let t = Instant::now();
        out = f();
        runs.push(t.elapsed().as_secs_f64() * 1000.0);
    }
    let same = if out == reference { "identical" } else { "DIFFERENT" };
    println!("  {label:<34} {:7.2} ms  {:>6.1} MB  {same}", median(runs), out.len() as f64 / 1e6);
}

/// The canonical object, with components serialized independently and spliced in; key order follows the struct.
fn parallel<S: Fn(&dyn erased::Ser) -> Vec<u8> + Sync>(
    output: &caliper_docgen_core::types::ExtractionOutput,
    ser: S,
) -> Vec<u8> {
    let parts: Vec<Vec<u8>> = output
        .components
        .par_iter()
        .map(|(k, v)| {
            let mut b = ser(&k);
            b.push(b':');
            b.extend(ser(v));
            b
        })
        .collect();
    let mut buf = Vec::with_capacity(parts.iter().map(Vec::len).sum::<usize>() + 1 << 20);
    buf.extend_from_slice(b"{\"components\":{");
    for (i, p) in parts.iter().enumerate() {
        if i > 0 {
            buf.push(b',');
        }
        buf.extend_from_slice(p);
    }
    buf.push(b'}');
    // Remaining top-level fields, in declaration order, taken from a full serialization of an empty-components copy.
    let mut rest = output.clone();
    rest.components.clear();
    let tail = ser(&rest);
    let tail = &tail[b"{\"components\":{}".len()..];
    buf.extend_from_slice(tail);
    buf
}

mod erased {
    pub trait Ser: erased_serde_like::Sealed {}
    pub mod erased_serde_like {
        pub trait Sealed {}
    }
}

fn main() {
    let src = std::env::args().nth(1).expect("usage: jsonbench DIR");
    let options = PipelineOptions { src_dirs: vec![src.into()], ..Default::default() };
    let output = extract(&options);
    let reference = serde_json::to_vec(&output).unwrap();
    println!("{} components, {:.1} MB", output.components.len(), reference.len() as f64 / 1e6);
    time("serde_json::to_vec", &reference, || serde_json::to_vec(&output).unwrap());
    time("sonic_rs::to_vec", &reference, || sonic_rs::to_vec(&output).unwrap());
    time("simd_json::serde::to_vec", &reference, || simd_json::serde::to_vec(&output).unwrap());
    let comps: Vec<_> = output.components.iter().collect();
    time("serde_json per component (rayon)", &reference, || {
        let parts: Vec<Vec<u8>> = comps
            .par_iter()
            .map(|(k, v)| {
                let mut b = serde_json::to_vec(k).unwrap();
                b.push(b':');
                serde_json::to_writer(&mut b, v).unwrap();
                b
            })
            .collect();
        splice(&output, parts, |x| serde_json::to_vec(x).unwrap())
    });
    time("sonic_rs per component (rayon)", &reference, || {
        let parts: Vec<Vec<u8>> = comps
            .par_iter()
            .map(|(k, v)| {
                let mut b = sonic_rs::to_vec(k).unwrap();
                b.push(b':');
                b.extend(sonic_rs::to_vec(v).unwrap());
                b
            })
            .collect();
        splice(&output, parts, |x| sonic_rs::to_vec(x).unwrap())
    });
    let _ = parallel::<fn(&dyn erased::Ser) -> Vec<u8>>;
    // Reading the output back, as a consumer would.
    let mut runs = (Vec::new(), Vec::new());
    for _ in 0..11 {
        let t = Instant::now();
        let v: serde_json::Value = serde_json::from_slice(&reference).unwrap();
        runs.0.push(t.elapsed().as_secs_f64() * 1000.0);
        drop(v);
        let t = Instant::now();
        let v: sonic_rs::Value = sonic_rs::from_slice(&reference).unwrap();
        runs.1.push(t.elapsed().as_secs_f64() * 1000.0);
        drop(v);
    }
    println!("  parse to Value: serde_json {:.2} ms, sonic_rs {:.2} ms", median(runs.0), median(runs.1));
}

fn splice<F: Fn(&caliper_docgen_core::types::ExtractionOutput) -> Vec<u8>>(
    output: &caliper_docgen_core::types::ExtractionOutput,
    parts: Vec<Vec<u8>>,
    ser: F,
) -> Vec<u8> {
    let mut buf = Vec::with_capacity(parts.iter().map(Vec::len).sum::<usize>() + (1 << 20));
    buf.extend_from_slice(b"{\"components\":{");
    for (i, p) in parts.iter().enumerate() {
        if i > 0 {
            buf.push(b',');
        }
        buf.extend_from_slice(p);
    }
    buf.push(b'}');
    let mut rest = output.clone();
    rest.components.clear();
    let tail = ser(&rest);
    buf.extend_from_slice(&tail[b"{\"components\":{}".len()..]);
    buf
}

