434	/// Diagnostics merged by identity: an identical diagnostic reported while resolving many components is kept once,
435	/// listing those components in `affects`.
436	#[derive(Default)]
437	struct DiagnosticSet {
438	    index: FxHashMap<Diagnostic, usize>,
439	    items: Vec<Diagnostic>,
440	}
441	
442	impl DiagnosticSet {
443	    fn add(&mut self, diagnostic: Diagnostic, component: Option<&str>) {
444	        let at = match self.index.get(&diagnostic) {
445	            Some(&at) => at,
446	            None => {
447	                self.index.insert(diagnostic.clone(), self.items.len());
448	                self.items.push(diagnostic);
449	                self.items.len() - 1
450	            }
451	        };
452	        if let Some(key) = component {
453	            self.items[at].affects.push(key.to_owned());
454	        }
455	    }
456	
457	    fn extend(&mut self, diagnostics: impl IntoIterator<Item = Diagnostic>, component: Option<&str>) {
458	        for diagnostic in diagnostics {
459	            self.add(diagnostic, component);
460	        }
461	    }
462	
463	    /// The diagnostics by file, position and message; run-wide ones (no file) first.
464	    fn finish(self) -> Vec<Diagnostic> {
465	        let mut items = self.items;
466	        for diagnostic in &mut items {
467	            diagnostic.affects.sort();
468	            diagnostic.affects.dedup();
469	        }
470	        // Severity by explicit rank, worst first, and code by name: neither enum's declaration order is an ordering.
471	        items.sort_by(|a, b| {
472	            (&a.file, a.line, a.column, &a.message)
473	                .cmp(&(&b.file, b.line, b.column, &b.message))
474	                .then_with(|| severity_rank(&b.severity).cmp(&severity_rank(&a.severity)))
475	                .then_with(|| format!("{:?}", a.code).cmp(&format!("{:?}", b.code)))
476	                .then_with(|| a.help.cmp(&b.help))
477	        });
478	        items
479	    }
480	}
