482	/// Read and parse one source file, through the parse cache for `.d.ts`.
483	fn parse_source_file(path: &Utf8Path, cache: &DtsCache) -> (SourceData, Option<Diagnostic>) {
484	    let is_dts = path.as_str().ends_with(".d.ts");
485	    let (source, io_diag) = match std::fs::read_to_string(path) {
486	        Ok(s) => (s, None),
487	        Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
488	    };
489	    if is_dts {
490	        if let Some(cached) = cache.get(path, &source) {
491	            return (cached, io_diag);
492	        }
493	    }
494	    let data = crate::extractor::parse_file(path, &source);
495	    if is_dts {
496	        cache.insert(path, &source, data.clone());
497	    }
498	    (data, io_diag)
499	}
