6	/// Returns the process exit code (0 = success, 2 = extraction reported an
7	/// error-severity diagnostic) rather than calling `std::process::exit`
8	/// directly — keeps the exit decision testable and lets `main()` be the only
9	/// place that actually terminates the process.
10	pub fn cmd_extract(args: crate::ExtractArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
11	    use indicatif::{ProgressBar, ProgressStyle};
12	
13	    let html_attributes = args.html_attributes.map(|m| match m {
14	        crate::HtmlAttributeModeArg::Curated => "curated",
15	        crate::HtmlAttributeModeArg::Full => "full",
16	        crate::HtmlAttributeModeArg::None => "none",
17	    });
18	    let options = build_options(BuildOptionsArgs {
19	        src: &args.src,
20	        cache_dir: args.cache_dir.as_deref(),
21	        html_attributes,
22	        config_path,
23	        extra_builtins: &args.extra_builtins,
24	    })?;
25	
26	    let pb = if !quiet && !args.json {
27	        let pb = ProgressBar::new_spinner();
28	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
29	        pb.set_message("Extracting...");
30	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
31	        Some(pb)
32	    } else {
33	        None
34	    };
35	
36	    let output = caliper_docgen_core::pipeline::extract(&options);
37	
38	    if let Some(pb) = pb {
39	        pb.finish_and_clear();
40	    }
41	
42	    // --json ignores --out/--format — see ExtractArgs::json's doc comment.
43	    if args.json {
44	        println!("{}", serde_json::to_string(&output).into_diagnostic()?);
45	    } else {
46	        if !quiet {
47	            print_summary(&output, quiet);
48	            print_diagnostics(&output.diagnostics);
49	        }
50	
51	        let json = match args.format {
52	            crate::OutputFormat::Canonical => serde_json::to_string_pretty(&output).into_diagnostic()?,
53	            crate::OutputFormat::Rdt => serialize_rdt(&output).into_diagnostic()?,
54	            crate::OutputFormat::Storybook => serialize_storybook(&output).into_diagnostic()?,
55	            crate::OutputFormat::Toon => caliper_docgen_core::toon::render_output_toon(&output),
56	        };
57	
58	        match args.out {
59	            Some(ref path) => write_atomic(path, &json).into_diagnostic().wrap_err(format!("Writing to {path}"))?,
60	            None => println!("{json}"),
61	        }
62	    }
63	
64	    // Must run regardless of --json — this is the one thing CI actually
65	    // depends on the exit code for.
66	    Ok(output.exit_code(false))
67	}
