69	/// RDT's type-name convention for literal unions: `{"name": "enum", "value": [...]}`
70	/// instead of inlining the literal text into `type.name` as a plain string. Lets
71	/// prop-table renderers that pattern-match `type.name === "enum"` (a common
72	/// Storybook addon integration point) show a `<select>` control for the most
73	/// common, most curated props in any design system (variant, size, color…).
74	fn rdt_type_json(prop_type: &caliper_docgen_core::types::PropType) -> serde_json::Value {
75	    use caliper_docgen_core::types::PropType;
76	
77	    if prop_type.is_literal_union() {
78	        let values: Vec<serde_json::Value> = match prop_type {
79	            PropType::Union(members) => members.iter().map(|m| serde_json::json!({"value": m.raw_string()})).collect(),
80	            PropType::LiteralUnion { members, .. } => {
81	                members.iter().map(|m| serde_json::json!({"value": format!("\"{m}\"")})).collect()
82	            }
83	            _ => vec![],
84	        };
85	        return serde_json::json!({ "name": "enum", "value": values });
86	    }
87	    serde_json::json!({ "name": prop_type.raw_string() })
88	}
