90	/// RDT's default `skipChildrenPropWithoutDoc`: an undocumented `children` says nothing a
91	/// prop table can show, so RDT never emits it. Canonical output keeps it.
92	fn rdt_omits(prop: &caliper_docgen_core::types::ParsedProp) -> bool {
93	    prop.name == "children" && prop.description.is_empty()
