96	/// `methods` is always `[]` — this tool doesn't extract class methods, and RDT
97	/// consumers (Storybook's docgen addon) only ever read it for class components.
98	pub fn serialize_rdt(output: &caliper_docgen_core::types::ExtractionOutput) -> serde_json::Result<String> {
99	    let mut map = serde_json::Map::new();
100	    for (name, entry) in &output.components {
101	        let props: serde_json::Map<String, serde_json::Value> = entry
102	            .props
103	            .iter()
104	            .filter(|(_, prop)| !rdt_omits(prop))
105	            .map(|(k, prop)| {
106	                let obj = serde_json::json!({
107	                    "name": prop.name,
108	                    "type": rdt_type_json(&prop.prop_type),
109	                    "required": prop.required,
110	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value, "computed": d.computed})),
111	                    "description": prop.description,
112	                    "parent": prop.parent.as_ref().map(|p| serde_json::json!({"name": p.name, "fileName": p.file_name})),
113	                });
114	                (k.clone(), obj)
115	            })
116	            .collect();
117	        map.insert(
118	            name.clone(),
119	            serde_json::json!({
120	                "displayName": entry.display_name,
121	                "props": serde_json::Value::Object(props),
122	                "description": entry.description,
123	                "methods": [],
124	                "tags": entry.tags,
125	                "composes": entry.composes,
126	            }),
127	        );
128	    }
129	    serde_json::to_string_pretty(&serde_json::Value::Object(map))
130	}
