        out.serialize_field("affectedFiles", affected_files)?;
        out.serialize_field("diagnostics", diagnostics)?;
        out.serialize_field("removedDiagnostics", removed_diagnostics)?;
        out.serialize_field("durationMs", duration_ms)?;
        out.end()
    }
}

