    let namespaces: Vec<(&str, &str)> = data
        .exports
        .iter()
        .filter_map(|e| match e {
            LexedExport::ReExportNamespace { namespace, source_specifier } => {
                Some((namespace.as_str(), source_specifier.as_str()))
            }
            _ => None,
        })
        .collect();
