def gh(state):
    out = subprocess.run(['gh', 'pr', 'list', '--state', state, '--limit', '300', '--json', 'headRefName,number,mergedAt'],
                         capture_output=True, text=True, check=True).stdout
    return json.loads(out)

merged = {p['headRefName']: p['number'] for p in gh('merged')}
closed = {p['headRefName']: p['number'] for p in gh('closed') if not p.get('mergedAt')}
open_ = {p['headRefName'] for p in gh('open')}
heads = subprocess.run(['/usr/bin/git', 'ls-remote', '--heads', 'origin'], capture_output=True, text=True, check=True).stdout
remote = sorted(line.split('refs/heads/', 1)[1] for line in heads.splitlines())

print('== merged PR, not open:')
for b in remote:
    if b in merged and b not in open_:
        print(f'  {b}\t#{merged[b]}')
print('== closed unmerged PR, not open:')
for b in remote:
    if b in closed and b not in open_ and b not in merged:
        print(f'  {b}\t#{closed[b]}')
print('== no PR:')
for b in remote:
    if b not in merged and b not in closed and b not in open_:
        print(f'  {b}')

