23	/// One-path-at-a-time filesystem seam. In particular, `scan` reads only one
24	/// directory; the recursor owns the breadth-first work queue.
25	pub(super) trait Scanner: Send {
26		fn classify(&self, path: &Path, follow_symlinks: bool) -> io::Result<EntryKind>;
27		fn canonicalize(&self, path: &Path) -> io::Result<PathBuf>;
28		fn scan(&self, path: &Path, visit: &mut dyn FnMut(io::Result<PathBuf>)) -> io::Result<()>;
