40	impl Scanner for FsScanner {
41		fn classify(&self, path: &Path, follow_symlinks: bool) -> io::Result<EntryKind> {
42			let link_metadata = fs::symlink_metadata(path)?;
43			if link_metadata.file_type().is_symlink() && !follow_symlinks {
44				return Ok(EntryKind::NonFollowedSymlink);
45			}
46	
47			let metadata = if link_metadata.file_type().is_symlink() {
48				match fs::metadata(path) {
49					Ok(metadata) => metadata,
50					Err(error) if error.kind() == io::ErrorKind::NotFound => {
51						return Ok(EntryKind::Other)
52					}
53					Err(error) => return Err(error),
54				}
55			} else {
56				link_metadata
57			};
58	
59			if metadata.is_dir() {
60				Ok(EntryKind::Directory(fs::canonicalize(path)?))
61			} else {
62				Ok(EntryKind::Other)
63			}
64		}
65	
66		fn canonicalize(&self, path: &Path) -> io::Result<PathBuf> {
67			fs::canonicalize(path)
68		}
69	
70		fn scan(&self, path: &Path, visit: &mut dyn FnMut(io::Result<PathBuf>)) -> io::Result<()> {
71			for entry in fs::read_dir(path)? {
72				visit(entry.map(|entry| entry.path()));
73			}
74			Ok(())
75		}
76	}
