388				self.coverage_pending = true;
389				self.coverage_work_pending = true;
390				self.replay_desired.clear();
391				self.replay_queue.clear();
392				self.rebuild_exclusions.clear();
393				self.resource_latched = false;
394				self.restart_epoch_work();
395				return;
396			}
397	
398			// Preserve every registration which was known-good before the uncertain
399			// mutation. Replay is performed directly on the fresh backend before a
400			// scanner failure can affect that coverage.
401			let mut desired = std::mem::take(&mut self.replay_desired);
402			let mut logical = std::mem::take(&mut self.logical);
403			for (identity, physical) in &self.physical {
404				let mut logicals: Vec<_> = physical
405					.logicals
406					.iter()
407					.filter(|path| !self.rebuild_exclusions.contains(*path))
408					.filter(|path| {
409						!self
410							.removed_prefixes
411							.iter()
412							.any(|prefix| path.starts_with(prefix))
413					})
414					.filter_map(|path| logical.remove(path).map(|watch| (path.clone(), watch)))
415					.collect();
416				if logicals.is_empty() {
417					continue;
418				}
419				logicals.sort_by(|(left, _), (right, _)| left.cmp(right));
420				let watch_path = if logicals
421					.iter()
422					.any(|(path, _)| path == &physical.watch_path)
423				{
424					physical.watch_path.clone()
425				} else {
426					logicals[0].0.clone()
427				};
428				desired.insert(
429					identity.clone(),
430					ReplayWatch {
431						watch_path,
432						mode: physical.mode,
433						logicals,
434					},
435				);
436			}
437			self.rebuild_exclusions.clear();
438	
439			// Drop the uncertain watcher before trying to create its replacement. This
440			// also releases inotify handles/watches which may be the scarce resource.
441			self.backend = Box::new(DisconnectedBackend);
442			self.physical.clear();
443			self.sweep.clear();
444			self.resource_latched = false;
445			self.replay_desired = desired;
446			self.replay_queue.clear();
447			self.requeue_replay();
448			self.restart_epoch_work();
