455		pub(super) fn replay_count(&self) -> usize {
456			if self.strategy == RecursionStrategy::RecursiveRoots {
457				return self.coverage_desired.len().max(1);
458			}
459			self.replay_desired
460				.len()
461				.saturating_add(self.physical.len())
462				.saturating_add(self.guards.len())
