469		pub(super) fn replay_backend_snapshot(&mut self) -> StepResult {
470			if self.strategy == RecursionStrategy::RecursiveRoots {
471				self.work.retain(|work| !matches!(work, Work::Coverage));
472				let mut result = StepResult::default();
473				self.step_coverage(&mut result);
474				return result;
475			}
476	
477			let mut combined = StepResult::default();
478			let budget = self.replay_queue.len();
479			for _ in 0..budget {
480				let Some(identity) = self.replay_queue.pop_front() else {
481					break;
482				};
483				let mut step = StepResult::default();
484				self.step_replay(identity, &mut step);
485				combined.errors.append(&mut step.errors);
486				combined.rebuild_backend |= step.rebuild_backend;
487				if combined.rebuild_backend || self.resource_latched {
488					return combined;
489				}
490			}
491	
492			let guard_roots: Vec<_> = self.root_guards.keys().cloned().collect();
493			for root in guard_roots {
494				let mut step = StepResult::default();
495				self.ensure_guard(root, &mut step);
496				combined.errors.append(&mut step.errors);
497				combined.rebuild_backend |= step.rebuild_backend;
498				if combined.rebuild_backend || self.resource_latched {
499					break;
500				}
501			}
502			combined
503		}
