612		fn projected_topology_paths(&self, path: &Path) -> Vec<PathBuf> {
613			let mut projected = HashSet::from([path.to_owned()]);
614			if let Some(physical) = self.physical.get(&Identity::Canonical(path.to_owned())) {
615				projected.extend(physical.logicals.iter().chain(&physical.guards).cloned());
616			}
617			let Some(parent) = path.parent() else {
618				return projected.into_iter().collect();
619			};
620			let Some(name) = path.file_name() else {
621				return projected.into_iter().collect();
622			};
623			let mut identities: HashSet<_> = self
624				.logical
625				.get(parent)
626				.map(|watch| &watch.identity)
627				.into_iter()
628				.chain(self.guards.get(parent).map(|watch| &watch.identity))
629				.cloned()
630				.collect();
631			identities.insert(Identity::Canonical(parent.to_owned()));
632			for identity in identities {
633				let Some(physical) = self.physical.get(&identity) else {
634					continue;
635				};
636				for alias in physical.logicals.iter().chain(&physical.guards) {
637					projected.insert(alias.join(name));
638				}
639			}
640			let mut projected: Vec<_> = projected.into_iter().collect();
641			projected.sort();
642			projected
643		}
