645		fn clear_authoritative_prefix(&mut self, path: &Path) {
646			self.removed_prefixes
647				.retain(|prefix| !prefix.starts_with(path) && !path.starts_with(prefix));
648			self.skipped_additions
649				.retain(|candidate| !candidate.starts_with(path));
650			self.addition_failures
651				.retain(|candidate, _| !candidate.starts_with(path));
652		}
653	
654		fn requeue_guarded_roots_below(&mut self, path: &Path) {
655			let guarded: Vec<_> = self
656				.root_guards
657				.keys()
658				.filter(|root| root.path.starts_with(path))
659				.cloned()
660				.collect();
661			for root in guarded {
662				// Run before a probe can prune queued work below the newly-created
663				// ancestor. This moves the guard down one or more levels immediately.
664				self.work.push_front(Work::Guard(root));
665			}
666		}
667	
668		fn requeue_configured_roots_below(&mut self, path: &Path) {
669			let roots: Vec<_> = self
670				.roots
671				.iter()
672				.filter(|root| root.path.starts_with(path))
673				.cloned()
674				.collect();
675			for root in roots {
676				self.seen.remove(&root);
677				let already_queued = self.work.iter().any(
678					|work| matches!(work, Work::Root(queued) | Work::Guard(queued) if queued == &root),
679				);
680				if !already_queued {
681					self.work.push_back(Work::Root(root));
682				}
683			}
684		}
