686		pub(super) fn step(&mut self) -> StepResult {
687			let mut result = StepResult::default();
688	
689			if self.rebuild_requested {
690				self.rebuild_requested = false;
691				result.rebuild_backend = true;
692				return result;
693			}
694	
695			if let Some(identity) = self.replay_queue.pop_front() {
696				self.step_replay(identity, &mut result);
697				return result;
698			}
699	
700			if let Some(path) = self.pending_removals.pop_front() {
701				self.pending_removal_set.remove(&path);
702				self.remove_logical(&path, &mut result);
703				return result;
704			}
705	
706			if let Some((path, root)) = self.pending_owner_removals.pop_front() {
707				let entry = SweepEntry {
708					path,
709					root,
710					epoch: self.epoch,
711				};
712				self.remove_owner_force(entry, &mut result);
713				return result;
714			}
715	
716			if self.refresh_tombstones {
717				self.removed_prefixes.clear();
718				self.refresh_tombstones = false;
719			}
720	
721			if let Some(work) = self.work.pop_front() {
722				self.step_work(work, &mut result);
723				return result;
724			}
725	
726			match self.phase {
727				Phase::Traversing => {
728					self.prepare_sweep();
729					if self.sweep.is_empty() {
730						self.settle();
731					}
732				}
733				Phase::Sweeping => {
734					if let Some(entry) = self.sweep.pop_front() {
735						self.remove_owner(entry, &mut result);
736					} else {
737						self.settle();
738					}
739				}
740				Phase::Settled => {}
741			}
742	
743			result
744		}
