746		fn begin_epoch(&mut self) {
747			self.epoch = self
748				.epoch
749				.checked_add(1)
750				.expect("filesystem recursion epoch overflow");
751			self.resource_latched = false;
752			self.resource_reported = false;
753			self.skipped_additions.clear();
754			self.addition_failures.clear();
755			self.rebuild_exclusions.clear();
756			self.refresh_tombstones = true;
757			self.restart_epoch_work();
758		}
759	
760		fn restart_epoch_work(&mut self) {
761			self.work.clear();
762			self.seen.clear();
763			self.sweep.clear();
764			self.phase = Phase::Traversing;
765			self.retry_roots.retain(|root| self.roots.contains(root));
766			self.retry_candidates
767				.retain(|(root, _)| self.roots.contains(root));
768			self.requeue_replay();
769			let mut roots: Vec<_> = self.roots.iter().cloned().collect();
770			roots.sort_by(|left, right| {
771				left.path
772					.cmp(&right.path)
773					.then_with(|| right.recursive.cmp(&left.recursive))
774			});
775			if self.coverage_work_pending {
776				self.work.push_back(Work::Coverage);
777			}
778			if self.is_managed() {
779				let mut guarded: Vec<_> = self.root_guards.keys().cloned().collect();
780				guarded.sort_by(|left, right| left.path.cmp(&right.path));
781				self.work.extend(guarded.into_iter().map(Work::Guard));
782				self.work.extend(
783					self.retry_candidates
784						.iter()
785						.filter(|(root, _)| self.roots.contains(root))
786						.cloned()
787						.map(|(root, path)| Work::Candidate {
788							root,
789							path,
790							transient_retries: TRANSIENT_RETRIES,
791						}),
792				);
793			}
794			self.work.extend(
795				self.retry_roots
796					.iter()
797					.filter(|root| self.roots.contains(*root))
798					.cloned()
799					.map(Work::Root),
800			);
801			self.work.extend(roots.into_iter().map(Work::Root));
802		}
803	
804		fn requeue_replay(&mut self) {
805			let queued: HashSet<_> = self.replay_queue.iter().cloned().collect();
806			let mut replay: Vec<_> = self
807				.replay_desired
808				.iter()
809				.filter(|(identity, _)| !queued.contains(*identity))
810				.map(|(identity, watch)| (watch.watch_path.clone(), identity.clone()))
811				.collect();
812			replay.sort_by(|(left, _), (right, _)| left.cmp(right));
813			self.replay_queue
814				.extend(replay.into_iter().map(|(_, identity)| identity));
815		}
816	
817		fn schedule_retries(&mut self) {
818			self.resource_latched = false;
819			self.requeue_replay();
820	
821			let mut roots: Vec<_> = self
822				.retry_roots
823				.iter()
824				.filter(|root| self.roots.contains(*root))
825				.cloned()
826				.collect();
827			roots.sort_by(|left, right| left.path.cmp(&right.path));
828			self.work.extend(roots.into_iter().map(Work::Root));
829	
830			let mut candidates: Vec<_> = self
831				.retry_candidates
832				.iter()
833				.filter(|(root, _)| self.roots.contains(root))
834				.cloned()
835				.collect();
836			candidates.sort_by(|(_, left), (_, right)| left.cmp(right));
837			self.work
838				.extend(candidates.into_iter().map(|(root, path)| Work::Candidate {
839					root,
840					path,
841					transient_retries: TRANSIENT_RETRIES,
842				}));
843		}
844	
845		fn step_replay(&mut self, identity: Identity, result: &mut StepResult) {
846			if self.resource_latched {
847				self.replay_queue.clear();
848				return;
849			}
850			let Some(mut replay) = self.replay_desired.remove(&identity) else {
851				return;
852			};
853	
854			loop {
855				if self.skipped_additions.contains(&replay.watch_path) {
856					if let Some((path, _)) = replay
857						.logicals
858						.iter()
859						.find(|(path, _)| !self.skipped_additions.contains(path))
860					{
861						replay.watch_path.clone_from(path);
862					} else {
863						return;
864					}
865				}
866	
867				let attempted = replay.watch_path.clone();
868				match self.backend.watch(&attempted, replay.mode) {
869					Ok(()) => {
870						if !self.verify_poll_registration(&attempted, &identity, result) {
871							return;
872						}
873						self.addition_failures.remove(&attempted);
874						let logicals = replay
875							.logicals
876							.iter()
877							.map(|(path, _)| path.clone())
878							.collect();
879						self.physical.insert(
880							identity.clone(),
881							PhysicalWatch {
882								watch_path: attempted,
883								logicals,
884								guards: HashSet::new(),
885								mode: replay.mode,
886								registered: true,
887							},
888						);
889						for (path, watch) in replay.logicals {
890							self.logical.insert(path, watch);
891						}
892						return;
893					}
894					Err(error) => {
895						if path_not_found(&error) {
896							result.errors.extend(notify_multi_path_errors(
897								self.kind,
898								WatchedPath::non_recursive(attempted.clone()),
899								error,
900								false,
901							));
902							self.addition_failures.remove(&attempted);
903							self.skipped_additions.remove(&attempted);
904							if let Some(path) = self.retain_valid_replay_aliases(
905								&mut replay,
906								&identity,
907								&attempted,
908								result,
909							) {
910								replay.watch_path = path;
911								continue;
912							}
913						} else if let Some(resource) = classify_resource_error(&error) {
914							self.resource_latched = true;
915							self.replay_queue.clear();
916							if !self.resource_reported {
917								self.resource_reported = true;
918								let error = resource.into_fs_error(error);
919								result.errors.push(RuntimeError::FsWatcher {
920									kind: self.kind,
921									err: error,
922								});
923							}
924							self.replay_desired.insert(identity, replay);
925						} else {
926							let failures = self.addition_failures.entry(attempted.clone()).or_default();
927							*failures = failures.saturating_add(1);
928							result.errors.extend(notify_multi_path_errors(
929								self.kind,
930								WatchedPath::non_recursive(attempted.clone()),
931								error,
932								false,
933							));
934							if *failures >= 2 {
935								self.skipped_additions.insert(attempted);
936							} else {
937								self.replay_desired.insert(identity, replay);
938								result.rebuild_backend = true;
939							}
940						}
941						return;
942					}
943				}
944			}
945		}
946	
947		fn retain_valid_replay_aliases(
948			&self,
949			replay: &mut ReplayWatch,
950			identity: &Identity,
951			failed: &Path,
952			result: &mut StepResult,
953		) -> Option<PathBuf> {
954			let mut representative = None;
955			replay.logicals.retain(|(path, _)| {
956				if path == failed
957					|| self.skipped_additions.contains(path)
958					|| self
959						.removed_prefixes
960						.iter()
961						.any(|prefix| path.starts_with(prefix))
962				{
963					return false;
964				}
965	
966				let valid = match self.scanner.classify(path, self.follow_symlinks) {
967					Ok(EntryKind::Directory(canonical)) => identity == &Identity::Canonical(canonical),
968					Ok(EntryKind::Other) => identity == &Identity::Lexical(path.clone()),
969					Ok(EntryKind::NonFollowedSymlink) => false,
970					Err(error) => {
971						result.errors.push(self.scan_error(path.clone(), error));
972						false
973					}
974				};
975				if valid && representative.is_none() {
976					representative = Some(path.clone());
977				}
978				valid
979			});
980			representative
981		}
982	
983		fn step_work(&mut self, work: Work, result: &mut StepResult) {
984			match work {
985				Work::Coverage => self.step_coverage(result),
986				Work::Guard(root) => self.step_guard(root, result),
987				Work::Root(root) => self.step_root(root, result),
988				Work::Candidate {
989					root,
990					path,
991					transient_retries,
992				} => self.step_candidate(root, path, transient_retries, result),
993				Work::Scan {
994					root,
995					path,
996					transient_retries,
997				} => self.step_scan(root, path, transient_retries, result),
998				Work::Probe(path) => self.step_probe(path, result),
999			}
1000		}
1001	
1002		fn step_coverage(&mut self, result: &mut StepResult) {
1003			if self.strategy != RecursionStrategy::RecursiveRoots
1004				|| !self.coverage_pending
1005				|| !self.coverage_work_pending
1006			{
1007				return;
1008			}
1009			self.coverage_work_pending = false;
1010	
1011			if self.coverage_desired.is_empty() {
1012				self.coverage_desired = self.build_coverage(result);
1013			}
1014			let requests: Vec<_> = self
1015				.coverage_desired
1016				.iter()
1017				.filter(|desired| !self.skipped_additions.contains(&desired.path))
1018				.filter(|desired| {
1019					!self.coverage_installed.iter().any(|installed| {
1020						installed.path == desired.path
1021							&& installed.canonical == desired.canonical
1022							&& mode_satisfies(installed.mode, desired.mode)
1023					})
1024				})
1025				.cloned()
1026				.collect();
1027			if requests.is_empty() {
1028				self.coverage_pending = false;
1029				return;
1030			}
1031	
1032			let watches: Vec<_> = requests
1033				.iter()
1034				.map(|watch| (watch.path.clone(), watch.mode))
1035				.collect();
1036			let BatchWatchResult {
1037				errors,
1038				commit_error,
1039			} = self.backend.watch_batch(&watches);
1040			let mut failed = HashSet::new();
1041			let mut refresh_desired = false;
1042			for (path, error) in errors {
1043				failed.insert(path.clone());
1044				if path_not_found(&error) {
1045					result.errors.extend(notify_multi_path_errors(
1046						self.kind,
1047						WatchedPath::recursive(path),
1048						error,
1049						false,
1050					));
1051					refresh_desired = true;
1052					result.rebuild_backend = true;
1053				} else if let Some(resource) = classify_resource_error(&error) {
1054					self.resource_latched = true;
1055					if !self.resource_reported {
1056						self.resource_reported = true;
1057						result.errors.push(RuntimeError::FsWatcher {
1058							kind: self.kind,
1059							err: resource.into_fs_error(error),
1060						});
1061					}
1062				} else {
1063					let failures = self.addition_failures.entry(path.clone()).or_default();
1064					*failures = failures.saturating_add(1);
1065					result.errors.extend(notify_multi_path_errors(
1066						self.kind,
1067						WatchedPath::recursive(path.clone()),
1068						error,
1069						false,
1070					));
1071					if *failures >= 2 {
1072						self.skipped_additions.insert(path);
1073					} else {
1074						result.rebuild_backend = true;
1075					}
1076				}
1077			}
1078	
1079			if let Some(error) = commit_error {
1080				let path = requests
1081					.first()
1082					.map_or_else(|| self.cwd.clone(), |watch| watch.path.clone());
1083				result.errors.extend(notify_multi_path_errors(
1084					self.kind,
1085					WatchedPath::recursive(path),
1086					error,
1087					false,
