def clean(x):
    return re.sub(r' \(.*\)$', '', x)


def norm(x):
    x = clean(x).split('/')[-1].split('.')[-1]
    return re.sub(r'[^a-z0-9]', '', x.lower())


def plausible(name):
    base = clean(name).split('/')[-1]
    return bool(re.match(r'[A-Z]', base)) and not re.match(r'use[A-Z]', base) and not base.startswith('generate')


rdt = json.load(open(f'{res}/{n}.rdt.dump.json'))
raw = open(f'{res}/{n}.caliper.dump.json').read()
cal = json.loads(raw[raw.index('{'):])['components']
by_file = defaultdict(list)
for key, c in cal.items():
    by_file[c['filePath']].append((norm(c['displayName']), set(c['props']), key, c))

parents = Counter()
examples = defaultdict(list)
per_component = Counter()
unmatched = []
for comp in rdt:
    if not plausible(comp['name']):
        continue
    mine = {p: v for p, v in comp['props'].items() if (f'bench-inputs/{n}/') in v['parent'] and '/node_modules/' not in v['parent']}
    if not mine:
        continue
    match = None
    for nm, props, key, c in by_file.get(comp['file'], []):
        if nm == norm(comp['name']) or len(set(mine) & props) >= max(1, len(mine) // 2):
            match = (props, key, c)
            break
    if match is None:
        unmatched.append(f"{comp['name']}  {comp['file'].split('bench-inputs/')[-1]}")
