            parent = v['parent'].split('::')[-1] if '::' in v['parent'] else v['parent'].split('/')[-1]
            parents[parent] += 1
            per_component[key] += 1
            if len(examples[parent]) < 3:
                examples[parent].append(f'{key}.{p}')

